const seriesBank = [
  { series: 'সাধারণ জ্ঞান ও আশ্চর্য তথ্য',
    angles: ['প্রতিদিনের জিনিসের অজানা ইতিহাস','মানবদেহ নিয়ে আশ্চর্য তথ্য','বিশ্বের অদ্ভুত রেকর্ড','প্রাণিজগতের অবিশ্বাস্য ক্ষমতা'] },
  { series: 'বিজ্ঞান ব্যাখ্যা',
    angles: ['দৈনন্দিন ঘটনার পেছনের বিজ্ঞান','মহাবিশ্ব ও মহাকাশ','আবহাওয়া ও জলবায়ু কীভাবে কাজ করে','শরীরে ওষুধ কীভাবে কাজ করে'] },
  { series: 'বাংলাদেশের ইতিহাস ও ভূরাজনীতি',
    angles: ['নদী ও সীমানার ইতিহাস','মুক্তিযুদ্ধের কম-জানা অধ্যায়','প্রতিবেশী দেশের সঙ্গে বাংলাদেশের সম্পর্ক','বাংলাদেশের অর্থনীতির মোড় ঘোরানো ঘটনা'] },
  { series: 'AI লিটারেসি',
    angles: ['AI টুল দিয়ে পড়াশোনা ও কাজ','ডিপফেক ও ভুয়া কনটেন্ট চেনার উপায়','AI চ্যাটবটের সীমাবদ্ধতা','ভবিষ্যতের চাকরিতে AI-এর প্রভাব'] },
  { series: 'মিথ-বাস্টিং',
    angles: ['স্বাস্থ্য নিয়ে প্রচলিত ভুল ধারণা','খাবার নিয়ে মিথ','ভাইরাল ভুয়া দাবি যাচাই','প্রযুক্তি নিয়ে মিথ'] },
  { series: 'টাকা ও bKash নিরাপত্তা',
    angles: ['bKash প্রতারণার কৌশল ও বাঁচার উপায়','OTP ও PIN নিরাপত্তা','অনলাইন কেনাকাটায় প্রতারণা চেনা','সঞ্চয় ও বাজেটের মৌলিক নিয়ম'] },
];

const staticData = $getWorkflowStaticData('global');
const counter = staticData.dayCounter || 0;
staticData.dayCounter = counter + 1;

const entry = seriesBank[counter % seriesBank.length];
const angle = entry.angles[Math.floor(counter / seriesBank.length) % entry.angles.length];

return [{
  json: {
    dayIndex: counter,
    series: entry.series,
    topicAngle: angle,
    slotDateDhaka: new Date().toISOString()
  }
}];

const resp = $json.response || '';
const prev = $('Topic Rotation').first().json;
const stamp = new Date().toISOString();
const slug = 'draft-' + stamp.replace(/[:.]/g, '-') + '-day' + prev.dayIndex;
const draft = {
  series: prev.series,
  topicAngle: prev.topicAngle,
  dayIndex: prev.dayIndex,
  generatedAt: stamp,
  model: 'llama3.2:3b',
  outline: resp,
  status: 'draft-in-queue'
};
const content = JSON.stringify(draft, null, 2);
return [{
  json: {
    fileName: slug + '.json',
    fileContentBase64: Buffer.from(content, 'utf8').toString('base64'),
    series: prev.series,
    topicAngle: prev.topicAngle
  }
}];
